# 暴力卷积 O(n log n)
def dirichlet_conv(f, g, n):
  h = [0]*(n+1)
  for d in range(1, n+1):
    for k in range(1, n//d + 1):
      h[d*k] += f[d] * g[k]
  return h

# 莫比乌斯反演: g = f*1  =>  f = g*μ
# 杜教筛: S(n) = Σ_{i<=n} h(i), h = f*g, 选好 g 使前缀和可求

